-- The sessions of the setup UI. The cookie holds a random token. This table
-- holds only the SHA-256 hash of that token: a database read does not give a
-- usable cookie. A row has no IP address and no user agent.
--
-- The Better Auth table "session" stays unchanged for a revert to the
-- TypeScript service. Do not edit this file after release: SQLx checks its
-- hash.
CREATE TABLE IF NOT EXISTS app_sessions (
  token_hash BYTEA PRIMARY KEY CHECK (octet_length(token_hash) = 32),
  user_id TEXT NOT NULL REFERENCES "user" ("id") ON DELETE CASCADE,
  created_at TIMESTAMPTZ NOT NULL,
  expires_at TIMESTAMPTZ NOT NULL,
  CHECK (expires_at > created_at)
);

CREATE INDEX IF NOT EXISTS app_sessions_user_id_idx ON app_sessions (user_id);
CREATE INDEX IF NOT EXISTS app_sessions_expires_at_idx ON app_sessions (expires_at);
